import { Directive, ElementRef, OnInit } from '@angular/core';

@Directive({
  selector: '[hgImageColoredHandler]'
})
export class ImageColoredHandlerDirective implements OnInit {
  constructor(private elementRef: ElementRef) {}

  ngOnInit(): void {
    onLoadColoredImage(this.elementRef);
  }
}

export function onLoadColoredImage(elementRef: ElementRef) {
  const rootElem = elementRef.nativeElement as HTMLElement;
  Array.from(rootElem.querySelectorAll<HTMLImageElement>('img[color-class]')).forEach(elem => {
    elem.onload = _ev => {
      elem.parentElement.classList.add(elem.getAttribute('color-class'));
    };
  });
}
