import {
  ChangeDetectorRef,
  Directive,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  OnInit,
  Output,
  Renderer2,
  ViewChild
} from '@angular/core';
import { Router } from '@angular/router';
import { AccountService } from '@honoregaming/account';
import { DepositTax, OperatorConfiguration } from '@honoregaming/configuration';
import { BroadcastingService, PaymentFailure, roundNumber, TaxesService } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { MessageService } from '@honoregaming/ui';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import { getPaymentFailure } from '../../helpers/generic-payment-utils.helper';
import { ProviderBaseComponent } from '../provider-base.component';

interface DepositErrorResponse {
  error?: {
    code?: PaymentFailure;
    additionalData?: {
      infos?: Record<string, unknown>;
    };
  };
}

@Directive()
export abstract class DepositProviderBaseComponent extends ProviderBaseComponent implements OnInit {
  @Input() isPopin: boolean = false;

  @Output() depositSuccess: EventEmitter<void> = new EventEmitter<void>();

  @HostBinding('class.popin') get popinClass(): boolean {
    return this.isPopin;
  }

  hasSubmit: boolean = true;
  depositTax?: DepositTax;
  uniqueProvider!: boolean;
  currency: string;
  numberOfDecimals: number;
  amount!: number;
  selectedInnerProvider!: string;
  step!: number;
  logoToDisplay!: string;

  loading: boolean = false;
  isValid: boolean = false;
  submitted: boolean = false;
  providerUpper!: string;
  failure: string | null = null;
  failureInfos?: Record<string, unknown>;
  customerDepositPredefinedAmount?: number[];

  @ViewChild('input') input?: ElementRef;

  protected constructor(
    protected readonly taxesService: TaxesService,
    protected readonly messageService: MessageService,
    protected readonly i18nService: I18nService,
    protected readonly operatorConfiguration: OperatorConfiguration,
    protected readonly renderer: Renderer2,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly bcService: BroadcastingService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    protected readonly accountService: AccountService
  ) {
    super(taxesService, messageService, i18nService, router, transactionPopupService, accountService);
    this.currency = operatorConfiguration.currency.symbol;
    this.numberOfDecimals = operatorConfiguration.currency.numberOfDecimals;
  }

  ngOnInit(): void {
    if (this.provider.isDepositTaxActive) {
      this.depositTax = this.taxesService.getDepositTaxConfiguration();
    }
    this.initProvider();
  }

  get canSubmit(): boolean {
    return this.isValid && !this.loading;
  }

  updateAmount(value: number): void {
    const newValue: number = value != null ? this.i18nService.unformatNumber('' + value) : value;

    if (!Number.isNaN(newValue) && this.amount !== newValue) {
      this.amount = newValue;
      return;
    }

    const newAmount: number = roundNumber(this.amount, this.numberOfDecimals);
    this.renderer.setProperty(
      this.input?.nativeElement,
      'value',
      newAmount ? this.i18nService.formatNumberSync(newAmount) : ''
    );
  }

  checkValidity(value: number): void {
    this.isValid = false;

    const newValue: number = +(value == null ? value : this.i18nService.unformatNumber('' + value));

    if (Number.isNaN(newValue) || newValue <= 0) {
      return;
    }

    const meetsMinimum: boolean = !this.provider.minDeposit || newValue >= this.provider.minDeposit;
    const meetsMaximum: boolean = !this.provider.maxDeposit || newValue <= this.provider.maxDeposit;

    this.isValid = !!this.provider && meetsMinimum && meetsMaximum;

    if (this.isValid) {
      this.amount = newValue;
    }
  }

  protected initProvider(): void {
    this.providerUpper = this.provider.providerName.toUpperCase();

    if (this.provider.parentProviderName?.toString() !== this.provider.providerName) {
      this.selectedInnerProvider = this.provider.providerName;
    }

    this.step = 1;
    this.logoToDisplay = this.provider.logoPath;
    this.bcService.broadcast('payment-provider-scroll-to-top');
  }

  protected resolveTranslationKey(suffix: string, fallbackSuffix: string): string {
    const providerKey: string = 'ACCOUNT.DEPOSIT.' + this.providerUpper + '.PLACEHOLDER.' + suffix;

    return this.i18nService.translationKeyExistsSync(providerKey)
      ? providerKey
      : 'ACCOUNT.DEPOSIT.PLACEHOLDER.' + fallbackSuffix;
  }

  protected handleDepositError(error: DepositErrorResponse): void {
    this.failure = getPaymentFailure(error.error?.code);
    this.failureInfos = error.error?.additionalData?.infos;
  }
}
