import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit, Renderer2 } from '@angular/core';
import { Router } from '@angular/router';
import { Observable, of } from 'rxjs';
import { catchError, finalize, take, takeUntil, tap } from 'rxjs/operators';
import { operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { Async, AsyncTrigger, BroadcastingService, TaxesService } from '@honoregaming/core';
import { AuthService, CustomerState, Me } from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { MessageService } from '@honoregaming/ui';
import { WithdrawProvider } from 'projects/customer/hg-account/src/lib/models/withdraw-provider.model';
import { AccountService } from 'projects/customer/hg-account/src/lib/services/account.service';
import { TransactionPopupService } from 'projects/customer/hg-core/src/lib/services/transaction-popup.service';
import { WithdrawConfirmationComponent } from '../withdraw-confirmation/withdraw-confirmation.component';
import { WithdrawProviderBaseComponent } from '../../provider-base';
import { GenericTransactionResponse } from '../../models/generic-transaction-response.model';

interface BettingShopContent {
  content: string;
  title: string;
  style: string;
}

@Component({
  selector: 'hg-withdraw-provider',
  templateUrl: './withdraw-provider.component.html',
  styleUrls: ['./withdraw-provider.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WithdrawProviderComponent extends WithdrawProviderBaseComponent implements OnInit, WithdrawProvider {
  userState?: CustomerState;
  message?: string;
  balance?: number;
  withdrawalDelayHours?: number;
  withdrawalDelayMinutes?: number;
  content?: BettingShopContent;
  isLoading: boolean = false;

  @AsyncTrigger() languageTrigger = this.i18nService.languageChanged$;

  constructor(
    protected readonly accountService: AccountService,
    private readonly authService: AuthService,
    protected readonly i18nService: I18nService,
    protected readonly renderer: Renderer2,
    protected readonly bcService: BroadcastingService,
    protected readonly messageService: MessageService,
    protected readonly cdRef: ChangeDetectorRef,
    protected readonly taxesService: TaxesService,
    private readonly contentService: ContentService,
    protected readonly router: Router,
    protected readonly transactionPopupService: TransactionPopupService,
    @Inject(operatorConfigurationToken) protected readonly operatorConfiguration: OperatorConfiguration
  ) {
    super(
      taxesService,
      messageService,
      i18nService,
      operatorConfiguration,
      renderer,
      cdRef,
      bcService,
      router,
      transactionPopupService,
      accountService
    );
  }

  ngOnInit(): void {
    super.ngOnInit();
    this.loadContent();
    this.init().pipe(takeUntil(this.destroy$)).subscribe();
    this.withdrawalDelayHours = Math.floor(this.withdrawalDelay / 60);
    this.withdrawalDelayMinutes = this.withdrawalDelay % 60;
  }

  submitWithdraw(): void {
    if (!this.input) {
      return;
    }

    this.updateAmount(this.input.nativeElement.value);
    this.loading = true;
    this.failure = null;
    this.accountService
      .createWithdraw(this.provider, this.amount)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.authService.getBalance().subscribe();
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        (response: GenericTransactionResponse) => {
          this.messageService
            .sendComponentMessage(WithdrawConfirmationComponent, { voucherNumber: response.value })
            .closed.subscribe(() => {
              this.withdrawValidated.emit();
              this.withdrawSuccess.emit();
              this.cdRef.markForCheck();
            });
        },
        (error: unknown) => {
          this.handleWithdrawError(error);
        }
      );
  }

  @Async()
  private loadContent(): void {
    this.isLoading = true;

    this.contentService
      .getContent('betting-shop-withdrawal-content')
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        }),
        catchError(() => of(null))
      )
      .subscribe((content: BettingShopContent | null) => {
        if (content) {
          this.content = content;
        }
      });
  }

  private init(): Observable<Me> {
    return this.authService.me$.pipe(
      take(1),
      tap(user => {
        this.balance = user.balance;
        this.userState = user.state;
      })
    );
  }
}
