import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DepositProviderComponent } from './deposit/deposit-provider.component';
import { WithdrawProviderComponent } from './withdraw/withdraw-provider.component';
import { HgI18nModule } from '@honoregaming/i18n';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { HgUiModule } from '@honoregaming/ui';
import { HgTemplatingModule } from '@honoregaming/templating';
import { WithdrawConfirmationComponent } from './withdraw-confirmation/withdraw-confirmation.component';

@NgModule({
  imports: [CommonModule, RouterModule, FormsModule, HgI18nModule, HgUiModule, HgTemplatingModule],
  declarations: [DepositProviderComponent, WithdrawConfirmationComponent, WithdrawProviderComponent]
})
export class BettingshopModule {
  static deposit = DepositProviderComponent;
  static withdraw = WithdrawProviderComponent;
  static depositPartner = DepositProviderComponent;
}
