import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, OnInit, Output } from '@angular/core';
import { of } from 'rxjs';
import { catchError, finalize, takeUntil } from 'rxjs/operators';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { DepositProvider } from 'projects/customer/hg-account/src/lib/models/deposit-provider.model';
import { Provider } from 'projects/customer/hg-account/src/lib/models/provider.model';

interface BettingShopContent {
  content: string;
  title: string;
  style: string;
}

@Component({
  selector: 'hg-deposit-provider',
  templateUrl: './deposit-provider.component.html',
  styleUrls: ['./deposit-provider.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DepositProviderComponent extends DestroySubject implements OnInit, DepositProvider {
  @Output() depositSuccess: EventEmitter<void> = new EventEmitter<void>();

  provider!: Provider;
  uniqueProvider!: boolean;
  isPopin: boolean = false;
  hasSubmit: boolean = false;
  canSubmit: boolean = false;
  customerDepositPredefinedAmount?: number[];
  content?: BettingShopContent;
  isLoading: boolean = false;

  @AsyncTrigger() languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private readonly cdRef: ChangeDetectorRef,
    private readonly contentService: ContentService,
    private readonly i18nService: I18nService
  ) {
    super();
  }

  ngOnInit(): void {
    this.load();
  }

  @Async()
  private load(): void {
    this.isLoading = true;

    this.contentService
      .getContent('betting-shop-deposit-content')
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        }),
        catchError(() => of(null))
      )
      .subscribe((content: BettingShopContent) => {
        this.content = content;
      });
  }

  submitDeposit(): void {}
}
