import { PaymentFailure } from '@honoregaming/core';

export function getPaymentFailure(failure: PaymentFailure) {
  switch (failure) {
    case PaymentFailure.LimitExceeded:
      return 'LIMIT_EXCEEDED';
    case PaymentFailure.ProviderOffline:
      return 'PROVIDER_OFFLINE';
    case PaymentFailure.CannotDoWithdraw:
      return 'CANNOT_DO_WITHDRAW';
    case PaymentFailure.InsufficientBalance:
      return 'INSUFFICIENT_BALANCE';
    case PaymentFailure.PaymentAccountNotValid:
      return 'PAYMENT_ACCOUNT_NOT_VALID';
    case PaymentFailure.Ambiguous:
      return 'AMBIGUOUS';
    case PaymentFailure.InvalidNumber:
      return 'INVALID_NUMBER';
    case PaymentFailure.InsufficientAmount:
      return 'INSUFFICIENT_AMOUNT';
    case PaymentFailure.Other:
      return 'OTHER';
    case PaymentFailure.InvalidCode:
      return 'INVALID_CODE';
    case PaymentFailure.CustomerNameNotMatch:
      return 'CUSTOMER_NAME_NOT_MATCH';
    case PaymentFailure.InvalidCustomerBankAccount:
      return 'INVALID_CUSTOMER_BANK_ACCOUNT';
    case PaymentFailure.CustomerAuthenticationFailed:
      return 'CONFIRM_PASSWORD';
    case PaymentFailure.DepositAmountAboveAuthorizedLimits:
    case PaymentFailure.WithdrawAmountAboveAuthorizedLimits:
      return 'ABOVE_LIMITS_AMOUNT';
    case PaymentFailure.DepositCountAboveAuthorizedLimits:
    case PaymentFailure.WithdrawCountAboveAuthorizedLimits:
      return 'ABOVE_LIMITS_COUNT';
    case PaymentFailure.CustomerIdentityNotValidated:
      return 'CUSTOMER_IDENTITY_NOT_VALIDATED';
    case PaymentFailure.CustomerLimitationExceeded:
      return 'CUSTOMER_DEPOSIT.LIMIT_REACHED';
    case PaymentFailure.GameSessionOpened:
      return 'GAME_SESSION_OPENED';
    default:
      return 'GENERIC';
  }
}
